import re
spec = """
REQ-1 WHEN 장비 알람이 5분 안에 3번 오면 THE SYSTEM SHALL 1선 담당자에게 티켓을 연다 [TEST-1]
REQ-2 THE SYSTEM SHALL 장애 원인을 빨리 찾는다
REQ-3 WHEN P1 티켓이 30분 넘게 열려 있으면 THE SYSTEM SHALL 현장대리인에게 호출한다
"""
for line in spec.strip().splitlines():
    rid, problems = line.split()[0], []
    if "SHALL" not in line: problems.append("SHALL 없음")
    if "WHEN" not in line and "WHILE" not in line: problems.append("조건(WHEN) 없음")
    if re.search(r"빨리|적절히|최대한", line): problems.append("잴 수 없는 말")
    if not re.search(r"\[TEST-\d+\]", line): problems.append("시험 번호 없음")
    print(rid, "통과" if not problems else "막힘: " + ", ".join(problems))
# REQ-1 통과
# REQ-2 막힘: 조건(WHEN) 없음, 잴 수 없는 말, 시험 번호 없음
# REQ-3 막힘: 시험 번호 없음
